import{_ as e,C as i,c as t,o as s,a0 as a,b as r,w as n,a as l,G as o,a1 as u}from"./chunks/framework.DKRgXLPU.js";const p=JSON.parse('{"title":"Guide de la séance : Introduction au jeu mental (2-3 heures)","description":"","frontmatter":{},"headers":[],"relativePath":"fr/mental-journey/session-guide.md","filePath":"fr/mental-journey/session-guide.md"}');const c=e({name:"fr/mental-journey/session-guide.md"},[["render",function(e,p,c,d,m,h){const g=i("Mermaid");return s(),t("div",null,[p[1]||(p[1]=a('<h1 id="guide-de-la-seance-introduction-au-jeu-mental-2-3-heures" tabindex="-1">Guide de la séance : Introduction au jeu mental (2-3 heures) <a class="header-anchor" href="#guide-de-la-seance-introduction-au-jeu-mental-2-3-heures" aria-label="Permalink to &quot;Guide de la séance : Introduction au jeu mental (2-3 heures)&quot;">​</a></h1><h2 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h2><p>Ce guide vous aide à animer une séance d&#39;initiation de 2 à 3 heures à la préparation mentale au jeu de pétanque. Idéal pour les entraîneurs, les responsables de club ou les joueurs expérimentés souhaitant initier leur équipe à l&#39;entraînement mental.</p><div class="tip custom-block"><p class="custom-block-title">Ce guide comporte deux sections.</p><ul><li><strong><a href="#for-participants">Pour les participants</a></strong> - Ce que les joueurs apprendront</li><li><strong><a href="#for-facilitators">Pour les animateurs</a></strong> - Comment mener la session</li></ul></div><h2 id="acces-rapide" tabindex="-1">Accès rapide <a class="header-anchor" href="#acces-rapide" aria-label="Permalink to &quot;Accès rapide&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>But</th><th>Accéder</th></tr></thead><tbody><tr><td><strong>Pour les participants</strong></td><td>À quoi s&#39;attendre de la session</td><td><a href="#pour-participants">Voir la section</a></td></tr><tr><td><strong>À l&#39;attention des animateurs</strong></td><td>Plan de séance complet et horaire</td><td><a href="#pour-animateurs">Voir la section</a></td></tr><tr><td><strong>Matériel de la session</strong></td><td>Guides, diapositives et feuilles de travail</td><td><a href="/en/mental-journey/materials">Voir les documents</a></td></tr><tr><td><strong>Liste de vérification des préparatifs</strong></td><td>Que faut-il préparer avant la séance ?</td><td><a href="#préparation-1-semaine-avant">Voir la liste de vérification</a></td></tr></tbody></table><hr><h2 id="pour-les-participants" tabindex="-1">Pour les participants <a class="header-anchor" href="#pour-les-participants" aria-label="Permalink to &quot;Pour les participants&quot;">​</a></h2><h3 id="a-quoi-s-39-attendre" tabindex="-1">À quoi s&#39;attendre <a class="header-anchor" href="#a-quoi-s-39-attendre" aria-label="Permalink to &quot;À quoi s&amp;#39;attendre&quot;">​</a></h3><p>Cette séance présente l&#39;aspect mental de la pétanque à travers des discussions, des exercices et des techniques pratiques que vous pouvez utiliser immédiatement.</p><p><strong>Vous apprendrez :</strong></p><ul><li>Pourquoi l&#39;entraînement mental est important pour la performance</li><li>La différence entre le « mode technique » et le « mode flux »</li><li>Comment reconnaître et gérer sa critique intérieure</li><li>Techniques simples de gestion de la pression</li><li>Une routine de base avant le tir</li></ul><p><strong>Ce dont vous aurez besoin :</strong></p><ul><li>Esprit ouvert et volonté de partager</li><li>Cahier et stylo</li><li>Vos propres expériences à partager</li><li>2 à 3 heures de temps concentré</li></ul><h3 id="structure-de-la-session" tabindex="-1">Structure de la session <a class="header-anchor" href="#structure-de-la-session" aria-label="Permalink to &quot;Structure de la session&quot;">​</a></h3>',15)),(s(),r(u,null,{default:n(()=>[o(g,{id:"mermaid-155",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BIntroduction%20%3Cbr%2F%3E%2020%20min%5D%20--%3E%20B%5BLa%20Zone%20%3Cbr%2F%3E%2040%20min%5D%0A%20%20%20%20B%20--%3E%20C%5BCasser%20%3Cbr%2F%3E%2010%20min%5D%0A%20%20%20%20C%20--%3E%20D%5BCritique%20int%C3%A9rieure%20%3Cbr%2F%3E%2040%20min%5D%0A%20%20%20%20D%20--%3E%20E%5BOutils%20pratiques%20%3Cbr%2F%3E%2040%20min%5D%0A%20%20%20%20E%20--%3E%20F%5BInt%C3%A9gration%20%3Cbr%2F%3E%2020%20min%5D%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23f3e5f5%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23c8e6c9%0A"})]),fallback:n(()=>[...p[0]||(p[0]=[l(" Loading... ",-1)])]),_:1})),p[2]||(p[2]=a('<h3 id="concepts-cles-que-vous-explorerez" tabindex="-1">Concepts clés que vous explorerez <a class="header-anchor" href="#concepts-cles-que-vous-explorerez" aria-label="Permalink to &quot;Concepts clés que vous explorerez&quot;">​</a></h3><h4 id="_1-la-zone-etat-d-39-ecoulement" tabindex="-1">1. La zone (état d&#39;écoulement) <a class="header-anchor" href="#_1-la-zone-etat-d-39-ecoulement" aria-label="Permalink to &quot;1. La zone (état d&amp;#39;écoulement)&quot;">​</a></h4><ul><li>Ce que l&#39;on ressent quand tout s&#39;emboîte parfaitement</li><li>Pourquoi le fait de réfléchir à la technique perturbe la performance</li><li>Le passage de la planification à l&#39;exécution</li></ul><h4 id="_2-le-critique-interieur" tabindex="-1">2. Le critique intérieur <a class="header-anchor" href="#_2-le-critique-interieur" aria-label="Permalink to &quot;2. Le critique intérieur&quot;">​</a></h4><ul><li>Comment le discours intérieur négatif affecte la performance</li><li>La différence entre le critique intérieur et le coach intérieur</li><li>observation neutre contre jugement sévère</li></ul><h4 id="_3-reponse-a-la-pression" tabindex="-1">3. Réponse à la pression <a class="header-anchor" href="#_3-reponse-a-la-pression" aria-label="Permalink to &quot;3. Réponse à la pression&quot;">​</a></h4><ul><li>Pourquoi votre jeu est différent en compétition</li><li>Signes physiques de pression</li><li>Techniques de réinitialisation rapide</li></ul><h4 id="_4-outils-pratiques" tabindex="-1">4. Outils pratiques <a class="header-anchor" href="#_4-outils-pratiques" aria-label="Permalink to &quot;4. Outils pratiques&quot;">​</a></h4><ul><li>Réinitialisation en 3 respirations</li><li>Routine simple avant le tir</li><li>Protocole de récupération des erreurs</li></ul><h3 id="que-faut-il-apporter" tabindex="-1">Que faut-il apporter ? <a class="header-anchor" href="#que-faut-il-apporter" aria-label="Permalink to &quot;Que faut-il apporter ?&quot;">​</a></h3><p><strong>Requis:</strong></p><ul><li>Vous-même et vos expériences</li><li>Volonté de participer</li></ul><p><strong>Facultatif:</strong></p><ul><li>Exemples de difficultés mentales auxquelles vous êtes confrontés</li><li>Questions sur des situations spécifiques</li><li>Carnet pour notes personnelles</li></ul><h3 id="apres-la-seance" tabindex="-1">Après la séance <a class="header-anchor" href="#apres-la-seance" aria-label="Permalink to &quot;Après la séance&quot;">​</a></h3><p>Vous recevrez :</p><ul><li>Résumé des concepts clés</li><li>Exercices pratiques pour la semaine</li><li>Liens vers des modules de formation détaillés</li><li>Modèle d&#39;objectif pour le développement mental dans le jeu</li></ul><hr><h2 id="pour-les-animateurs" tabindex="-1">Pour les animateurs <a class="header-anchor" href="#pour-les-animateurs" aria-label="Permalink to &quot;Pour les animateurs&quot;">​</a></h2><h3 id="liste-de-verification-de-preparation" tabindex="-1">Liste de vérification de préparation <a class="header-anchor" href="#liste-de-verification-de-preparation" aria-label="Permalink to &quot;Liste de vérification de préparation&quot;">​</a></h3><p><strong>Une semaine avant :</strong></p><ul><li>[ ] Réservez une chambre pour 2 à 3 heures.</li><li>[ ] Inviter 6 à 12 participants</li><li>[ ] Ajoutez les pages de documents à vos favoris (voir <a href="/en/mental-journey/materials">Materials</a>)</li><li>[ ] Examinez attentivement ce guide.</li><li>[ ] Préparez un tableau de conférence ou un tableau blanc.</li></ul><p><strong>La veille :</strong></p><ul><li>[ ] Confirmer la présence</li><li>[ ] Aménager la salle (disposition en cercle)</li><li>[ ] Tester toute technologie (diapositives, etc.)</li><li>[ ] Préparer les matériaux</li></ul><p><strong>1 heure avant :</strong></p><ul><li>[ ] Arrivez tôt</li><li>[ ] Disposez les sièges en cercle.</li><li>[ ] Matériel de préparation</li><li>[ ] Recentrez-vous</li></ul><h3 id="votre-role-de-facilitateur" tabindex="-1">Votre rôle de facilitateur <a class="header-anchor" href="#votre-role-de-facilitateur" aria-label="Permalink to &quot;Votre rôle de facilitateur&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Important</p><p>Vous n&#39;êtes <strong>pas</strong> un thérapeute ou un coach technique. Vous êtes un <strong>facilitateur</strong> qui :</p><ul><li>Discussion sur les guides</li><li>Crée un espace sûr</li><li>Relie les concepts à l&#39;expérience</li><li>Gère la dynamique de groupe</li></ul></div><p><strong>Compétences clés :</strong></p><ul><li>écoute active</li><li>présence neutre</li><li>Gérer les différentes personnalités</li><li>Savoir quand passer à autre chose</li></ul><h3 id="plan-de-seance-detaille" tabindex="-1">Plan de séance détaillé <a class="header-anchor" href="#plan-de-seance-detaille" aria-label="Permalink to &quot;Plan de séance détaillé&quot;">​</a></h3><hr><h4 id="partie-1-introduction-20-minutes" tabindex="-1">Partie 1 : Introduction (20 minutes) <a class="header-anchor" href="#partie-1-introduction-20-minutes" aria-label="Permalink to &quot;Partie 1 : Introduction (20 minutes)&quot;">​</a></h4><p><strong>Objectifs :</strong></p><ul><li>Créer un climat de confiance psychologique</li><li>Définissez les attentes</li><li>Créer des liens au sein du groupe</li></ul><p><strong>Scénario:</strong></p><p>« Bienvenue à tous. Cette séance porte sur l&#39;aspect mental de la pétanque : les pensées, les sentiments et les schémas qui influencent votre performance. »</p><p><strong>Règles de base :</strong></p><ol><li>Ce qui est partagé ici reste ici.</li><li>Aucun jugement sur les expériences des autres</li><li>La participation est volontaire.</li><li>Il n&#39;y a pas de mauvaises réponses</li></ol><p><strong>Questions rapides :</strong> Nom, depuis combien de temps vous jouez, un défi mental auquel vous êtes confronté.</p><p><strong>Notes à l&#39;intention du facilitateur :</strong></p><ul><li>Commencez par modéliser la vulnérabilité.</li><li>Les présentations doivent être brèves (1 min chacune).</li><li>Remarquez les thèmes communs</li><li>Valider toutes les réponses</li></ul><hr><h4 id="partie-2-l-39-etat-de-zone-d-39-ecoulement-40-minutes" tabindex="-1">Partie 2 : L&#39;état de zone / d&#39;écoulement (40 minutes) <a class="header-anchor" href="#partie-2-l-39-etat-de-zone-d-39-ecoulement-40-minutes" aria-label="Permalink to &quot;Partie 2 : L&amp;#39;état de zone / d&amp;#39;écoulement (40 minutes)&quot;">​</a></h4><p><strong>Objectifs :</strong></p><ul><li>Comprendre les états de flux</li><li>Distinguer le mode technique du mode fluide</li><li>Apprenez le concept de « commutateur ».</li></ul><p><strong>Question d&#39;ouverture :</strong> « Repensez à une fois où vous avez joué votre meilleure partie de pétanque. Qu’avez-vous ressenti ? Qu’est-ce qui était différent ? »</p><p><strong>Sujets de discussion :</strong></p><ol><li>« Combien d&#39;entre vous ont déjà vécu des parties où tout s&#39;est parfaitement enchaîné ? »</li><li>« À quoi pensiez-vous pendant ces moments-là ? »</li><li>« En quoi est-ce différent des moments où vous rencontrez des difficultés ? »</li></ol><p><strong>Points clés de l&#39;enseignement :</strong></p><p>Utilisez un tableau blanc pour dessiner :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLANNING MODE          →    EXECUTION MODE</span></span>\n<span class="line"><span>(Outside circle)            (Inside circle)</span></span>\n<span class="line"><span>- Analyze situation         - Eyes on target</span></span>\n<span class="line"><span>- Choose strategy           - Trust training</span></span>\n<span class="line"><span>- Decide throw type         - Automatic movement</span></span></code></pre></div><p><strong>Exercice : Le Switch (10 minutes)</strong></p><p>« Entraînons-nous au moment décisif : »</p><ol><li>Se lever</li><li>Imaginez que vous êtes à l&#39;extérieur du cercle - pensez à un tir</li><li>Respirez</li><li>Avancez (dans un cercle imaginaire)</li><li>Au fur et à mesure que vous avancez, lâchez prise sur l&#39;analyse.</li><li>Concentrez-vous uniquement sur une cible imaginaire.</li></ol><p><strong>Débriefing :</strong></p><ul><li>« Qu&#39;avez-vous remarqué ? »</li><li>« Était-ce facile ou difficile de lâcher prise ? »</li><li>« Comment cela pourrait-il s&#39;appliquer dans de vrais jeux ? »</li></ul><hr><h4 id="partie-3-pause-10-minutes" tabindex="-1">Partie 3 : Pause (10 minutes) <a class="header-anchor" href="#partie-3-pause-10-minutes" aria-label="Permalink to &quot;Partie 3 : Pause (10 minutes)&quot;">​</a></h4><p><strong>Actions du facilitateur :</strong></p><ul><li>Encourager les discussions informelles</li><li>Remarquez l&#39;énergie du groupe</li><li>Préparez-vous pour la section suivante</li></ul><hr><h4 id="partie-4-le-critique-interieur-40-minutes" tabindex="-1">Partie 4 : Le critique intérieur (40 minutes) <a class="header-anchor" href="#partie-4-le-critique-interieur-40-minutes" aria-label="Permalink to &quot;Partie 4 : Le critique intérieur (40 minutes)&quot;">​</a></h4><p><strong>Objectifs :</strong></p><ul><li>Reconnaître les schémas de discours intérieur négatifs</li><li>Distinguer le critique intérieur du coach intérieur</li><li>Pratiquer l&#39;observation neutre</li></ul><p><strong>Ouverture:</strong> « Nous avons tous une voix intérieure qui commente nos performances. Parfois, elle est constructive, parfois elle est dure. Explorons cela. »</p><p><strong>Exercice : Inventaire de la critique intérieure (15 minutes)</strong></p><p>« Sur votre feuille, écrivez :</p><ol><li>Ce que votre voix intérieure vous dit après un mauvais lancer</li><li>Ce que cela révèle sous pression</li><li>Ce que cela révèle de vos capacités</li></ol><p><em>Prévoyez 5 minutes pour écrire</em></p><p>«Alors, qui est prêt à donner un exemple ?»</p><p><strong>Notes à l&#39;intention du facilitateur :</strong></p><ul><li>Normaliser les pensées auto-soucieuses et sévères</li><li>N&#39;essayez pas de « réparer » qui que ce soit</li><li>Recherchez les schémas communs</li></ul><p><strong>Enseignement : Critique intérieure vs Coach intérieur (15 minutes)</strong></p><p>Tracez deux colonnes sur le tableau blanc :</p><table tabindex="0"><thead><tr><th>Critique intérieure</th><th>Coach intérieur</th></tr></thead><tbody><tr><td>« Comment as-tu pu rater ça ?! »</td><td>« Ça a mal tourné. »</td></tr><tr><td>«Tu t&#39;étouffes toujours.»</td><td>« Essayons encore. »</td></tr><tr><td>« Tu es terrible »</td><td>«Que puis-je apprendre ?»</td></tr></tbody></table><p><strong>Discussion:</strong></p><ul><li>«Vous remarquez la différence ?»</li><li>« Quelle voix améliore les performances ? »</li><li>« Pouvez-vous changer la voix ? »</li></ul><p><strong>Exercice pratique : Recadrage (10 minutes)</strong></p><p>«Prenez l&#39;une des phrases que vous prononcez avec votre critique intérieure. Comment un coach intérieur la formulerait-il ?»</p><p>Partagez des exemples.</p><hr><h4 id="partie-5-outils-pratiques-40-minutes" tabindex="-1">Partie 5 : Outils pratiques (40 minutes) <a class="header-anchor" href="#partie-5-outils-pratiques-40-minutes" aria-label="Permalink to &quot;Partie 5 : Outils pratiques (40 minutes)&quot;">​</a></h4><p><strong>Objectifs :</strong></p><ul><li>Apprenez la réinitialisation en 3 respirations</li><li>Créer une routine simple avant le tir</li><li>Comprendre la récupération des erreurs</li></ul><p><strong>Outil 1 : Réinitialisation en 3 respirations (10 minutes)</strong></p><p>« Ceci est votre bouton de réinitialisation d&#39;urgence. Utilisez-le lorsque vous sentez la pression monter. »</p><p><strong>Démontrer:</strong></p><ol><li>Inspirez pendant 4 secondes.</li><li>Tenir pendant 2 secondes</li><li>Expirez pendant 6 secondes.</li><li>Répéter 3 fois</li></ol><p>&quot;Entraînons-nous ensemble maintenant.&quot;</p><p><em>Animer le groupe à travers 3 cycles</em></p><p><strong>Débriefing :</strong></p><ul><li>« Qu’avez-vous remarqué dans votre corps ? »</li><li>« Dans quel cas pourriez-vous utiliser ceci ? »</li></ul><p><strong>Outil 2 : Routine simple avant la prise de vue (15 minutes)</strong></p><p>« Une routine vous aide à passer de la planification à l&#39;exécution de manière constante. »</p><p><strong>Structure de base :</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Outside Circle (Planning):</span></span>\n<span class="line"><span>- Look at situation</span></span>\n<span class="line"><span>- Decide on throw</span></span>\n<span class="line"><span>- See the result in your mind</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Walking to Circle (Transition):</span></span>\n<span class="line"><span>- One deep breath</span></span>\n<span class="line"><span>- Let go of analysis</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Inside Circle (Execution):</span></span>\n<span class="line"><span>- Eyes on target only</span></span>\n<span class="line"><span>- Trust your training</span></span>\n<span class="line"><span>- Execute</span></span></code></pre></div><p><strong>Exercice:</strong> « Créez votre propre routine en 3 étapes. Notez-la. »</p><p>Partagez des exemples.</p><p><strong>Outil 3 : Protocole de récupération des erreurs (15 minutes)</strong></p><p>« Les joueurs d&#39;élite ne font pas moins d&#39;erreurs. Ils se rétablissent plus vite. »</p><p><strong>Protocole en 3 étapes :</strong></p><ol><li><strong>Observer</strong> - Énoncer le fait de manière neutre (« Ça est parti à gauche »)</li><li><strong>Apprendre</strong> - Extraire des informations (« Le vent était plus fort que je ne le pensais »)</li><li><strong>Réinitialisation</strong> - Avancer (réinitialisation en 3 respirations, regard droit devant)</li></ol><p><strong>Pratique:</strong> « Pensez à une erreur récente. Suivez les 3 étapes. »</p><hr><h4 id="partie-6-integration-et-cloture-20-minutes" tabindex="-1">Partie 6 : Intégration et clôture (20 minutes) <a class="header-anchor" href="#partie-6-integration-et-cloture-20-minutes" aria-label="Permalink to &quot;Partie 6 : Intégration et clôture (20 minutes)&quot;">​</a></h4><p><strong>Objectifs :</strong></p><ul><li>Consolider les apprentissages</li><li>Élaborer des plans d&#39;action</li><li>Fournir des ressources</li></ul><p><strong>Questions de réflexion :</strong></p><ol><li>« Quel est le principal enseignement que vous retenez ? »</li><li>« Qu&#39;est-ce que tu vas essayer cette semaine ? »</li><li>« Quelles questions restent en suspens ? »</li></ol><p><strong>Planification des actions (10 minutes)</strong></p><p>« Sur votre document, écrivez :</p><ol><li>Une technique que vous pratiquerez cette semaine</li><li>Quand et où vous le pratiquerez</li><li>Comment vous suivrez vos progrès</li></ol><p><strong>Ressources:</strong></p><ul><li>Distribuer la fiche récapitulative</li><li>Partager le site web : carreau.app</li><li>Module de départ recommandé : <a href="/en/education/the-zone/">The Zone</a></li></ul><p><strong>Cercle de clôture :</strong> « Un mot pour décrire ce que vous ressentez en ce moment. »</p><p><strong>Messages finaux :</strong> « L’entraînement mental est une compétence comme une autre : il faut s’entraîner. Commencez petit à petit, soyez patient avec vous-même et observez les changements. Merci pour votre ouverture d’esprit aujourd’hui. »</p><hr><h3 id="conseils-pour-l-39-animateur" tabindex="-1">Conseils pour l&#39;animateur <a class="header-anchor" href="#conseils-pour-l-39-animateur" aria-label="Permalink to &quot;Conseils pour l&amp;#39;animateur&quot;">​</a></h3><h4 id="gerer-les-situations-difficiles" tabindex="-1">Gérer les situations difficiles <a class="header-anchor" href="#gerer-les-situations-difficiles" aria-label="Permalink to &quot;Gérer les situations difficiles&quot;">​</a></h4><p><strong>Si quelqu&#39;un domine :</strong></p><ul><li>« Merci [nom]. Écoutons les autres. »</li><li>Utilisez une prise de parole structurée</li></ul><p><strong>Si une personne est réticente :</strong></p><ul><li>Ne discutez pas</li><li>« C&#39;est un point de vue valable. Qu&#39;en pensent les autres ? »</li><li>S&#39;aligner sur leurs préoccupations</li></ul><p><strong>Si quelqu&#39;un s&#39;émeut :</strong></p><ul><li>Normalisez-le</li><li>« Cela touche à quelque chose de très réel. Merci de l&#39;avoir partagé. »</li><li>N&#39;essayez pas de réparer</li></ul><p><strong>Si la discussion s&#39;enlise :</strong></p><ul><li>Utilisez des invites spécifiques</li><li>Partagez votre propre exemple</li><li>Passez à un exercice</li></ul><h4 id="gestion-de-l-39-energie" tabindex="-1">Gestion de l&#39;énergie <a class="header-anchor" href="#gestion-de-l-39-energie" aria-label="Permalink to &quot;Gestion de l&amp;#39;énergie&quot;">​</a></h4><p><strong>Énergie élevée :</strong> Pratiquez des exercices et bougez. <strong>Faible énergie :</strong> Posez des questions provocatrices <strong>Dispersé :</strong> Remettre en ordre la structure <strong>Tension :</strong> Utilisez l&#39;humour ou faites une pause</p><h3 id="apres-la-seance-1" tabindex="-1">Après la séance <a class="header-anchor" href="#apres-la-seance-1" aria-label="Permalink to &quot;Après la séance&quot;">​</a></h3><p><strong>Suivi:</strong></p><ul><li>Envoyer un courriel récapitulatif dans les 24 heures</li><li>Inclure des liens vers les ressources</li><li>Proposez de répondre aux questions</li><li>Planifier une séance de suivi facultative</li></ul><p><strong>Auto-réflexion :</strong></p><ul><li>Qu&#39;est-ce qui a bien fonctionné ?</li><li>Que changeriez-vous ?</li><li>Qu&#39;est-ce qui vous a surpris ?</li><li>Qu&#39;avez-vous appris ?</li></ul><hr><h2 id="materiels" tabindex="-1">Matériels <a class="header-anchor" href="#materiels" aria-label="Permalink to &quot;Matériels&quot;">​</a></h2><ul><li><a href="/en/mental-journey/materials#participant-guide">Guide du participant</a></li><li><a href="/en/mental-journey/materials#facilitator-slides">Diapositives pour l&#39;animateur</a></li><li><a href="/en/mental-journey/materials#summary-sheet">Fiche récapitulative</a></li><li><a href="/en/mental-journey/materials#exercise-worksheets">Fiches d&#39;exercices</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Prêt à faciliter ?</p><ol><li>Examinez attentivement ce guide.</li><li>Télécharger les documents</li><li>Pratiquez les exercices vous-même</li><li>Planifiez votre séance</li><li>Ayez confiance dans le processus</li></ol></div>',140))])}]]);export{p as __pageData,c as default};
